require_once __DIR__.'/../lib/helpers.php';send_cors_headers();$type=trim((string)($_GET['type']??''));$slug=trim((string)($_GET['slug']??''));if(!in_array($type,['page','banner','blog','announcement','faq'],true))json_response(422,['success'=>false,'message'=>'Invalid content type.']);$sql='SELECT id,entry_type,slug,title,content_json,published_at FROM cms_entries WHERE entry_type=:type AND status="published" AND (starts_at IS NULL OR starts_at<=UTC_TIMESTAMP()) AND (ends_at IS NULL OR ends_at>=UTC_TIMESTAMP())';$params=['type'=>$type];if($slug!==''){$sql.=' AND slug=:slug LIMIT 1';$params['slug']=$slug;}else{$sql.=' ORDER BY COALESCE(published_at,created_at) DESC,created_at DESC';}$stmt=get_db()->prepare($sql);$stmt->execute($params);json_response(200,['success'=>true,$slug!==''?'entry':'entries'=>$slug!==''?($stmt->fetch()?:null):$stmt->fetchAll()]);
